from decimal import Decimal
from typing import Any


def _value(row: dict | None, column: str) -> Any:
    if row is None:
        return ""
    value = row.get(column, "")
    return "" if value is None else value


def _text(row: dict | None, column: str) -> str:
    value = _value(row, column)
    return value if isinstance(value, str) else str(value)


def _number(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _nvl(value: Any, default: Any) -> Any:
    return default if value is None or value == "" else value


def _date_ge(left: str, right: str) -> bool:
    if left == "00000000" or right == "00000000":
        return False
    return left >= right


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    errors: list[dict] = []

    stat_cd = _text(record, "STAT_CD")
    lost_rsn = _text(record, "LOST_RSN")
    close_dt = _text(record, "CLOSE_DT")
    amt = _number(_nvl(_value(record, "AMT"), 0))
    stage_pct = _number(_value(record, "STAGE_PCT"))

    if event in ("INSERT", "UPDATE"):
        if not (amt >= 0):
            errors.append(
                {
                    "code": "E3001",
                    "message": "Amount negative",
                    "severity": "BLOCK",
                }
            )

        if not (not (stat_cd == "W" and amt == 0)):
            errors.append(
                {
                    "code": "E3002",
                    "message": "Won opportunity requires amount",
                    "severity": "BLOCK",
                }
            )

        if not (not (stat_cd == "L" and lost_rsn == "")):
            errors.append(
                {
                    "code": "E3003",
                    "message": "Lost reason required",
                    "severity": "BLOCK",
                }
            )

        if not (not (stat_cd == "W" and close_dt == "00000000")):
            errors.append(
                {
                    "code": "E3004",
                    "message": "Won opportunity requires close date",
                    "severity": "BLOCK",
                }
            )

    if event == "UPDATE":
        old_stat_cd = _text(old, "STAT_CD")
        if not (not (old_stat_cd == "W" and stat_cd != "W")):
            errors.append(
                {
                    "code": "E3005",
                    "message": "Cannot reopen a won opportunity",
                    "severity": "BLOCK",
                }
            )

    if event in ("INSERT", "UPDATE"):
        stage_is_consistent = (
            (stat_cd == "P" and stage_pct == 10)
            or (stat_cd == "Q" and stage_pct == 25)
            or (stat_cd == "N" and stage_pct == 60)
            or (stat_cd == "W" and stage_pct == 100)
            or (stat_cd == "L" and stage_pct == 0)
        )
        if not stage_is_consistent:
            errors.append(
                {
                    "code": "E3006",
                    "message": "Stage percent inconsistent with status",
                    "severity": "BLOCK",
                }
            )

    if event == "INSERT":
        if not (close_dt == "00000000" or _date_ge(close_dt, today)):
            errors.append(
                {
                    "code": "E3007",
                    "message": "Close date in past",
                    "severity": "WARN",
                }
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
